DROP TABLE IF EXISTS `documentanalysis`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `documentanalysis` (
  `id` int NOT NULL AUTO_INCREMENT,
  `documentId` int NOT NULL,
  `status` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `provider` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'LOCAL_RULES',
  `model` longtext COLLATE utf8mb4_unicode_ci,
  `detectedType` longtext COLLATE utf8mb4_unicode_ci,
  `summary` longtext COLLATE utf8mb4_unicode_ci,
  `localExtractJson` longtext COLLATE utf8mb4_unicode_ci,
  `resultJson` longtext COLLATE utf8mb4_unicode_ci,
  `confidence` double DEFAULT NULL,
  `error` longtext COLLATE utf8mb4_unicode_ci,
  `requestedByUserId` int DEFAULT NULL,
  `startedAt` datetime(3) DEFAULT NULL,
  `completedAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `DocumentAnalysis_documentId_createdAt_idx` (`documentId`,`createdAt`),
  KEY `DocumentAnalysis_status_createdAt_idx` (`status`,`createdAt`),
  KEY `DocumentAnalysis_requestedByUserId_fkey` (`requestedByUserId`),
  CONSTRAINT `DocumentAnalysis_documentId_fkey` FOREIGN KEY (`documentId`) REFERENCES `document` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `DocumentAnalysis_requestedByUserId_fkey` FOREIGN KEY (`requestedByUserId`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

