  `designation` longtext COLLATE utf8mb4_unicode_ci,
  `officialEmail` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mobileNumber` longtext COLLATE utf8mb4_unicode_ci,
  `passwordHash` longtext COLLATE utf8mb4_unicode_ci,
  `passwordSalt` longtext COLLATE utf8mb4_unicode_ci,
  `primaryRole` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'LAB_COORDINATOR',
  `accountStatus` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNREGISTERED',
  `registeredAt` datetime(3) DEFAULT NULL,
  `approvedAt` datetime(3) DEFAULT NULL,
  `lastLoginAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
