DROP TABLE IF EXISTS `loginhistory`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `loginhistory` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int DEFAULT NULL,
  `labId` int DEFAULT NULL,
  `success` tinyint(1) NOT NULL,
  `ipAddress` longtext COLLATE utf8mb4_unicode_ci,
  `userAgent` longtext COLLATE utf8mb4_unicode_ci,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `LoginHistory_userId_createdAt_idx` (`userId`,`createdAt`),
  KEY `LoginHistory_labId_createdAt_idx` (`labId`,`createdAt`),
  KEY `LoginHistory_success_createdAt_idx` (`success`,`createdAt`),
  CONSTRAINT `LoginHistory_labId_fkey` FOREIGN KEY (`labId`) REFERENCES `lab` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `LoginHistory_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=243 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
