INSERT INTO `sopstage` VALUES (1,1,'SOP-01',1,'Master Technology Commercialisation Register','Maintain the single source of truth for technology identity, lab, PI, TRL/CRL, IP and commercialisation stage.',1,'Lab BD, PI, TMD, IPU','BDG',NULL,NULL),(2,1,'SOP-02',2,'Recording of ECF Commitments','Record every agreement/proposal/sanction/work order creating ECF within seven working days.',1,'Lab BD, PI','BDG',NULL,NULL),(3,1,'SOP-03',3,'Committed vs Actual Reconciliation','Reconcile due amounts with Lab BD-confirmed laboratory receipt information and explain variances.',1,'Lab BD, PI','BDG',NULL,NULL),(4,1,'SOP-04',4,'Business Value Capture','Capture direct, indirect, market, strategic and future revenue value.',1,'Lab BD, URDIP, IPU, TMD, ICM','BDG',NULL,NULL),(5,1,'SOP-05',5,'Impact Assessment Framework','Capture financial, social, environmental, socio-economic, strategic and intangible impact with evidence.',1,'Lab BD, PI, IMD','BDG',NULL,NULL),(6,1,'SOP-06',6,'Technology Impact Scoring','Apply the annual evidence-backed 100-point scoring matrix.',1,'TMD, IMD, URDIP, IPU','BDG',NULL,NULL),(7,1,'SOP-07',7,'Dashboard and Reporting','Submit monthly lab data and quarterly consolidated dashboards.',1,'Lab BD, CPD','BDG',NULL,NULL),(8,1,'SOP-08',8,'Variance Management and Escalation','Track overdue, disputed, deferred, under-verified and cancelled commitments.',1,'Lab BD, ICM, IPU, TMD, URDIP','BDG',NULL,NULL),(9,1,'SOP-09',9,'Controls, Audit Trail and Evidence','Require certified supporting evidence and version-controlled audit records.',1,'Lab BD, PI','BDG',NULL,NULL),(10,1,'SOP-10',10,'Review and Implementation','Coordinate phased implementation, quarterly review and annual impact reporting.',1,'BDG, CPD, IMD, TMD, IPU, URDIP, ICM, Lab BD','BDG',NULL,NULL);
/*!40000 ALTER TABLE `sopstage` ENABLE KEYS */;
UNLOCK TABLES;

